// Calibration of the PCRE2 match/stack limit emulation against official PHP.
// testdata/limits-corpus.json is generated by testdata/gencorpus -limits;
// testdata/limits.json is oracle/scripts/pcre-dump.php output on PHP 8.4.27
// (PCRE2 10.44, JIT on): the largest n for which preg_match on limitDoc(parts, n)
// does not fail, and the error PHP reports for n+1.
// Composer is MIT licensed, Copyright (c) Nils Adermann, Jordi Boggiano.

package pcre

import (
	"crypto/sha1"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"os"
	"strings"
	"testing"
)

// limitDoc mirrors limitDoc()/limitPart() of oracle/scripts/pcre-dump.php.
func limitDoc(parts string, n int) string {
	var b strings.Builder
	b.WriteString("{\n    \"name\": \"big/doc\"")
	for _, p := range parts {
		b.WriteString(",\n    ")
		var a []string
		switch p {
		case 'r':
			for i := 0; i < n; i++ {
				a = append(a, fmt.Sprintf("        \"vendor%d/package-%d\": \"^%d.0\"", i, i, i%7))
			}
			b.WriteString("\"require\": {\n" + strings.Join(a, ",\n") + "\n    }")
		case 'a':
			for i := 0; i < n; i++ {
				a = append(a, fmt.Sprintf("            \"Ns%d\\\\\\\\Sub\\\\\\\\\": \"packages/p%d/src\"", i, i))
			}
			b.WriteString("\"autoload\": {\"psr-4\": {\n" + strings.Join(a, ",\n") + "\n    }}")
		case 'e':
			for i := 0; i < n; i++ {
				a = append(a, fmt.Sprintf("{\"i\": %d, \"s\": \"v\\u00e9%d\", \"f\": %d.5e-1}", i, i, i))
			}
			b.WriteString("\"extra\": {\"list\": [" + strings.Join(a, ", ") + "]}")
		case 'n':
			for i := 0; i < n; i++ {
				switch i % 3 {
				case 0:
					a = append(a, fmt.Sprintf("-%d.25e+3", i))
				case 1:
					a = append(a, fmt.Sprint(i))
				default:
					a = append(a, fmt.Sprintf("0.%d", i))
				}
			}
			b.WriteString("\"nums\": [" + strings.Join(a, ",") + "]")
		case 's':
			for i := 0; i < n; i++ {
				a = append(a, fmt.Sprintf("\"x\\n\\\"y\\\\z\\/\\u0041%d\"", i))
			}
			b.WriteString("\"strs\": [" + strings.Join(a, ", ") + "]")
		case 'd':
			for i := 0; i < n; i++ {
				a = append(a, "[[[true, null], {}], [false]]")
			}
			b.WriteString("\"deep\": [" + strings.Join(a, ",") + "]")
		case 'w':
			for i := 0; i < n; i++ {
				a = append(a, "\n        {\n            \"k\" :  \"v\" ,\n            \"m\" :  [ 1 , 2 ]\n        }")
			}
			b.WriteString("\"ws\" : [" + strings.Join(a, " ,") + "\n    ]")
		case 'k':
			for i := 0; i < n; i++ {
				a = append(a, fmt.Sprintf("\"key%d\": \"v\"", i))
			}
			b.WriteString(strings.Join(a, ",\n    "))
		case 'A':
			b.WriteString("\"x\": " + strings.Repeat("[", n) + strings.Repeat("]", n) + ", \"require\": {}")
		case 'O':
			b.WriteString("\"x\": " + strings.Repeat(`{"a":`, n) + "1" + strings.Repeat("}", n) + ", \"require\": {}")
		}
	}
	b.WriteString("\n}")
	return b.String()
}

// tolerance of the emulated limits relative to PHP's thresholds
const limitTolerance = 0.02

func TestLimitCalibration(t *testing.T) {
	if testing.Short() {
		t.Skip("slow")
	}
	var c struct {
		Limits []struct {
			Name, Pattern, Parts string
		} `json:"limits"`
	}
	var o struct {
		Defines string `json:"defines"`
		Results []struct {
			N    int    `json:"n"`
			Err  *int   `json:"err"`
			SHA1 string `json:"sha1"`
		} `json:"results"`
	}
	for name, dst := range map[string]any{"testdata/limits-corpus.json": &c, "testdata/limits.json": &o} {
		data, err := os.ReadFile(name)
		if err != nil {
			t.Fatal(err)
		}
		if err := json.Unmarshal(data, dst); err != nil {
			t.Fatal(err)
		}
	}
	if len(c.Limits) != len(o.Results) {
		t.Fatal("corpus/oracle length mismatch")
	}
	for i, lc := range c.Limits {
		want := o.Results[i]
		re := MustGet(strings.ReplaceAll(lc.Pattern, "@@DEFINES@@", o.Defines))
		ok := limitDoc(lc.Parts, want.N)
		sum := sha1.Sum([]byte(ok))
		if hex.EncodeToString(sum[:]) != want.SHA1 {
			t.Fatalf("%s: limitDoc differs from the PHP generator", lc.Name)
		}
		okCost, okStack, _ := re.measure(ok)
		if want.Err == nil {
			// PHP never failed up to the search maximum
			if okCost > MatchLimit || okStack > StackLimit {
				t.Errorf("%s: n=%d passes in PHP but exceeds the emulated limits (cost %.3f, stack %.3f)", lc.Name, want.N, float64(okCost)/float64(MatchLimit), float64(okStack)/float64(StackLimit))
			}
			continue
		}
		failCost, failStack, _ := re.measure(limitDoc(lc.Parts, want.N+1))
		var okR, failR float64
		switch *want.Err {
		case 2: // PREG_BACKTRACK_LIMIT_ERROR
			okR, failR = float64(okCost)/float64(MatchLimit), float64(failCost)/float64(MatchLimit)
		case 6: // PREG_JIT_STACKLIMIT_ERROR
			okR, failR = float64(okStack)/float64(StackLimit), float64(failStack)/float64(StackLimit)
		default:
			t.Fatalf("%s: unexpected PHP error %d", lc.Name, *want.Err)
		}
		t.Logf("%-14s n=%5d err=%d ok=%.4f fail=%.4f", lc.Name, want.N, *want.Err, okR, failR)
		if okR > 1+limitTolerance || failR < 1-limitTolerance {
			t.Errorf("%s: emulated limit off by more than %.0f%% (ok %.4f, fail %.4f)", lc.Name, limitTolerance*100, okR, failR)
		}
	}
}
